-- ==========================================
-- SEED DATA ARDISTORE DIGITAL (SUPABASE)
-- Jalankan skrip ini di SQL Editor Supabase
-- ==========================================

-- 1. Kosongkan data lama jika ada
TRUNCATE TABLE public.products;
TRUNCATE TABLE public.faqs;

-- 2. Masukkan Semua Produk

-- 3. Masukkan Pertanyaan FAQ

-- 4. Berikan izin CRM untuk Tambah/Edit/Hapus Produk & FAQ
DROP POLICY IF EXISTS "Admins can insert products" ON public.products;
CREATE POLICY "Admins can insert products" ON public.products FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Admins can update products" ON public.products;
CREATE POLICY "Admins can update products" ON public.products FOR UPDATE USING (true);

DROP POLICY IF EXISTS "Admins can delete products" ON public.products;
CREATE POLICY "Admins can delete products" ON public.products FOR DELETE USING (true);

DROP POLICY IF EXISTS "Admins can insert faqs" ON public.faqs;
CREATE POLICY "Admins can insert faqs" ON public.faqs FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Admins can update faqs" ON public.faqs;
CREATE POLICY "Admins can update faqs" ON public.faqs FOR UPDATE USING (true);

DROP POLICY IF EXISTS "Admins can delete faqs" ON public.faqs;
CREATE POLICY "Admins can delete faqs" ON public.faqs FOR DELETE USING (true);

