INSERT INTO public.faqs (id, question, answer, is_active) VALUES ('faq-1', 'Apakah Tutor Rank Vs Bot MLBB aman dari banned?', 'Sangat aman! Metode yang digunakan adalah trik matchmaking sistem game Mobile Legends tanpa script cheat yang merusak file game, sehingga aman 100% dan tidak berisiko suspend/banned.', true);
INSERT INTO public.faqs (id, question, answer, is_active) VALUES ('faq-2', 'Berapa lama proses pembuatan akun atau pengiriman aplikasi?', 'Untuk akun Warlit dan App Premium (Netflix, Canva, Spotify), proses rata-rata selesai dalam 5-15 menit setelah konfirmasi pembayaran berhasil diverifikasi oleh admin.', true);
INSERT INTO public.faqs (id, question, answer, is_active) VALUES ('faq-3', 'Bagaimana sistem garansi di Ardistore Digital?', 'Semua produk memiliki garansi! Jika akun mengalami kendala atau tutor belum dipahami, admin kami akan membimbing secara personal atau memberikan replace akun baru.', true);
INSERT INTO public.faqs (id, question, answer, is_active) VALUES ('faq-4', 'Metode pembayaran apa saja yang diterima?', 'Kami menerima QRIS All Payment (BCA, Mandiri, BRI, BNI, DANA, GoPay, OVO, ShopeePay, LinkAja) sehingga Anda bisa membayar dari bank atau e-wallet mana saja secara instan.', true);
